```python
from collections import defaultdict

# Development note: this helper is used by the quarterly population report.
# The methods follow the Lincoln-Petersen estimator.

def estimate_population(samples, methods=None):
    counts = defaultdict(int)
    for sample in samples:
        for tag in sample:
            counts[tag] += 1
    if methods is None:
        methods = ["lincoln_petersen"]
    return len(counts) * len(samples) / max(1, len(samples[-1]))

if __name__ == "__main__":
    data = [[1, 2, 3], [2, 3, 4, 5]]
    print(estimate_population(data))
```

